const req=$('CASE003 Gate9 Kapso Webhook').first().json;
const headers=req.headers||{};
const calculated=String($input.first().json.signatureCalculated??$input.first().json.data??'').trim().toLowerCase();
const supplied=String(headers['x-webhook-signature']??'').trim().toLowerCase();
const safeEqual=(a,b)=>{let diff=a.length^b.length;const n=Math.max(a.length,b.length);for(let i=0;i<n;i++)diff|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return diff===0;};
const event=String(headers['x-webhook-event']??'');
const version=String(headers['x-webhook-payload-version']??'');
const eventId=String(headers['x-idempotency-key']??'');
return [{json:{
  signatureValid:supplied.length>0&&calculated.length>0&&safeEqual(calculated,supplied),
  eventValid:event==='whatsapp.message.received',
  versionValid:version==='v2',
  eventIdPresent:eventId.length>0,
  event,version,eventId
}}];

const req=$('CASE003 Gate9 Kapso Webhook').first().json;
const headers=req.headers||{};
const body=req.body||{};
if(body.batch===true) throw new Error('KAPSO_BATCH_NOT_SUPPORTED_GATE7');
const entry=body.data&&!Array.isArray(body.data)?body.data:body;
const message=entry.message||body.message;
const conversation=entry.conversation||body.conversation||{};
if(!message||!message.id) throw new Error('KAPSO_MESSAGE_ID_REQUIRED');
const kapso=message.kapso||{};
const direction=String(kapso.direction||'inbound');
if(direction!=='inbound') throw new Error('KAPSO_NON_INBOUND_MESSAGE');
const type=String(message.type||'unknown');
const mediaTypes=new Set(['image','video','audio','document','sticker']);
const mediaObject=mediaTypes.has(type)&&message[type]&&typeof message[type]==='object'?message[type]:null;
const textRaw=kapso.content??message.text?.body??mediaObject?.caption??message.caption??'';
const text=String(textRaw).trim();
if(!text) throw new Error('GATE7_TEXT_REQUIRED');
const providerPhoneNumberId=String(entry.phone_number_id||kapso.phone_number_id||conversation.phone_number_id||body.phone_number_id||'').trim();
if(!providerPhoneNumberId) throw new Error('KAPSO_PHONE_NUMBER_ID_REQUIRED');
const senderId=String(message.from||kapso.phone_number||conversation.phone_number||'').trim();
if(!senderId) throw new Error('KAPSO_SENDER_ID_REQUIRED');
const providerMessageId=String(message.id);
const providerEventId=String(headers['x-idempotency-key']||'');
const invoiceMatch=text.match(/(?:FACTURA|INVOICE)\s*[:=#-]?\s*([A-Z0-9-]{4,120})/i);
const taxMatch=text.match(/(?:RUC|TAX)\s*[:=#-]?\s*(\d{8,20})/i);
return [{json:{
  provider:'kapso',
  channel:'whatsapp',
  providerPhoneNumberId,
  providerEventId,
  providerMessageId,
  senderId,
  text,
  invoice_reference:invoiceMatch?.[1]||null,
  claimed_tax_id:taxMatch?.[1]||null,\n  verification_code:verificationCode,
  trace_id:providerEventId||providerMessageId,
  messageType:type
}}];

